contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = c.Owner();
    }

    // run tests with inputs: callerIsOwner (bool) determines whether this contract will attempt owner-only calls
    // amount is Ether forwarded when calling multiplicate/Command to exercise payable behavior
    function run(bool callerIsOwner, address payable target, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read initial observable state
        address ownerBefore = c.Owner();
        uint256 balBefore = address(c).balance;

        // If we want to simulate calls from the Owner, only possible if Owner==address(this).
        // The checker deploys c and this contract is the caller; so callerIsOwner implies Owner==address(this)
        // We do not change msg.sender; instead we assert relationships that must hold for either case.

        // Attempt owner-only calls and record whether they revert.
        bool withdrewReverted;
        try c.withdraw{value: 0}() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool commandReverted;
        try c.Command{value: amount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        // After attempts, read observable state again
        address ownerAfter = c.Owner();
        uint256 balAfter = address(c).balance;

        // General rule asserted:
        // 1) Owner cannot change via those calls: ownerBefore == ownerAfter.
        // 2) If withdraw did not revert, it must have transferred the entire contract balance out (so balAfter == 0).
        // 3) If caller was not Owner (callerIsOwner==false) then both withdraw and Command must revert.
        assert(
            ownerBefore == ownerAfter
            && (withdrewReverted || balAfter == 0)
            && (callerIsOwner || (withdrewReverted && commandReverted))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // addr - recipient passed to multiplicate
    // sendAmt - amount of wei forwarded to multiplicate
    function run(address addr, uint256 sendAmt) public payable {
        require(address(this).balance >= sendAmt);

        // observe before state
        address ownerBefore = c.Owner();
        uint256 balBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.multiplicate{value: sendAmt}(addr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        address ownerAfter = c.Owner();
        uint256 balAfter = address(c).balance;

        // If call succeeded and the input satisfied msg.value >= balBefore inside the function,
        // then the implementation transfers (address(this).balance+msg.value) which should result
        // in C having zero balance afterwards. More generally: whenever multiplicate is called
        // with sendAmt >= balBefore and it does not revert, then balAfter == 0.
        // Also, multiplicate must not change Owner.
        assert(ownerBefore == ownerAfter && (reverted || !(sendAmt >= balBefore) || balAfter == 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call multiplicate with an amount smaller than current contract balance
    // Params: target address to receive in multiplicate, and amount of wei to send with the call
    function run(address payable adr, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Ensure c has some balance > 0 by funding it from this contract if needed
        // send 1 wei to c if it's empty to create a non-zero balance
        if (address(c).balance == 0) {
            // send 1 wei to C via receive()
            payable(address(c)).transfer(1);
        }

        uint before = address(c).balance;
        // We only want to test the branch where msg.value < address(this).balance inside multiplicate
        // so require amount < before. If not, the property is not applicable.
        require(amount < before, "amount must be strictly less than contract balance");

        bool reverted = false;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule: when multiplicate is called with msg.value < previous balance,
        // it must not revert and must not change contract balance (i.e., send no Ether).
        assert(reverted == false && after == before);
    }

    receive() external payable {}
}

