contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: caller is this contract (not Owner of c), target address and calldata
    // We require zero value to simplify: Command shouldn't rely on Ether to bypass owner check.
    function run(address adr, bytes memory data) public payable {
        require(msg.value == 0);

        // Ensure this contract is not the Owner: the deployed c sets Owner = msg.sender at creation,
        // and the checker deploys a fresh c and passes it into our constructor, so our address is Owner.
        // To make this contract a non-owner, we perform a call to change Owner indirectly is impossible,
        // so instead we deploy the test assuming this contract is NOT the owner by requiring a different address param
        // However we cannot change c.Owner. So we instead check the observable behavior when an externally provided
        // caller (simulated by this contract) calls Command: for non-owner behavior we must force that this contract
        // is not Owner. To achieve that, require that c.Owner() != address(this).
        // This is a valid public observation.
        require(c.Owner() != address(this));

        bool reverted;
        try c.Command{value: 0}(adr, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if this contract is not Owner then calling Command with zero value must revert
        assert(reverted);
    }

    receive() external payable {}
}

